const STAGE_INFO={devices:{title:"Stage 1 - Emergency Equipment",objective:"Prepare the emergency room and select the required medical equipment before patient arrival.",icon:"🩺"},ecg:{title:"Stage 2 - ECG Monitoring",objective:"Analyze the patient's heart rhythm and decide the correct emergency action.",icon:"❤️"},repair:{title:"Stage 3 - Device Failure",objective:"Restore the defibrillator by connecting the damaged components correctly.",icon:"🔧"},stabilize:{title:"Stage 4 - Resuscitation",objective:"Perform emergency response procedures and stabilize the patient.",icon:"🚨"}};function showStageBriefing(e,n){const t=STAGE_INFO[e];t?(document.getElementById("timer").textContent="",stageContent.innerHTML=`\n\n\n    <div class="card briefing">\n\n\n        <div class="briefing-icon">\n\n            ${t.icon}\n\n        </div>\n\n\n\n        <h1>\n\n            ${t.title}\n\n        </h1>\n\n\n\n        <p>\n\n            ${t.objective}\n\n        </p>\n\n\n\n        <button id="begin-stage">\n\n            Begin Stage\n\n        </button>\n\n\n\n    </div>\n\n\n    `,document.getElementById("begin-stage").onclick=n):n()}